const items = $input.all();

return items.map((item) => {
  // The Basic LLM Chain usually returns its answer in "text".
  const raw =
    item.json.text ??
    item.json.output ??
    item.json.response ??
    item.json;

  let parsed;

  if (typeof raw === "string") {
    // Remove optional Markdown JSON code fences.
    let cleaned = raw
      .trim()
      .replace(/^```(?:json)?\s*/i, "")
      .replace(/\s*```$/, "")
      .trim();

    try {
      parsed = JSON.parse(cleaned);
    } catch {
      // Try to extract a JSON object if the model added text around it.
      const firstBrace = cleaned.indexOf("{");
      const lastBrace = cleaned.lastIndexOf("}");

      if (firstBrace !== -1 && lastBrace > firstBrace) {
        try {
          parsed = JSON.parse(cleaned.slice(firstBrace, lastBrace + 1));
        } catch {
          parsed = {
            status: "needs_information",
            body: cleaned,
          };
        }
      } else {
        parsed = {
          status: "needs_information",
          body: cleaned,
        };
      }
    }
  } else if (raw && typeof raw === "object") {
    parsed = raw;
  } else {
    parsed = {
      status: "needs_information",
      body: String(raw ?? ""),
    };
  }

  return {
    json: {
      status: parsed.status === "ready" ? "ready" : "needs_information",
      recipient_name: parsed.recipient_name ?? "",
      recipient_email: parsed.recipient_email ?? "",
      subject: parsed.subject ?? "",
      body: parsed.body ?? parsed.response ?? parsed.message ?? "",
    },
  };
});
